import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crimson/SeaStore Meeting 2023-04-05","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore Meeting 2023-04-05","date":"2023-04-05T00:00:00.000Z","updated":"2023-04-06T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson","OSD","MGR","CI","日志级别","池压缩"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-04-05.md","filePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-04-05.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-04-05.md"};function l(n,e,s,h,_,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<p>本次会议主要讨论了Ceph Crimson/SeaStore项目的进展和问题，以下是会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划：</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>QE团队更新</strong>：</p><ul><li><strong>OSD日志问题</strong>：发现OSD日志在调试级别20下未包含级别15、10、20的条目，而MGR日志则包含所有这些级别的条目。此问题先前在测试中已观察到，现已上报。</li><li><strong>池压缩问题</strong>：启用压缩的池在运行rados bench时，写入的数据量和对象数量与未启用压缩的池相同，而在Red Hat CEPH集群中，这些数据有明显差异。此问题也已上报。</li><li><strong>Crimson支持</strong>：下游的CI框架现已支持Crimson，所有CI管道中的测试将在未来几周内运行在Crimson构建上。</li></ul></li><li><p><strong>Crimson日志级别讨论</strong>：</p><ul><li>Crimson的日志系统与传统系统完全不同，只有Trace、Debug和Error三个级别。目前正在调整将传统的调试日志级别映射到Crimson的日志级别。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>跟进Milton关于设置最大对象的结果分享。</li><li>继续调试medusa oski系统，预计很快完成最终修改。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认Crimson日志级别映射的问题，并将与相关人员进一步沟通解决。</li><li>持续关注并解决池压缩问题。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>与Milton分享关于最大对象设置的测试结果。</li><li>完成medusa oski系统的最终调试和修改。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>提醒大家今天是Pierce的假期。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议于[具体时间]结束，感谢大家的参与。</li></ul><p>本次会议反映了Ceph Crimson/SeaStore项目的最新进展，强调了日志级别映射和池压缩问题的重要性，并制定了相应的后续行动计划。</p>',12)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
